scripts.pelt:
{"notes":["Empty, it takes no damage.","Summon Hound bites in and holds it open for 2 of its turns: every hit lands, Goku can't act, and it thrashes at her. The hold ends early if Goku falls.","On its 4th, 8th… turn it puts on the ally with the lowest HP%, and can be hurt until its next turn."],"init":"e=>{ e.hold = 0; e.worn = null; }","status":"e=>e.hold > 0 && gokuUp() ? `Held open by the hound for ${e.hold} more of its turns` : e.worn ? `Wearing ${e.worn.name}: takes damage until its next turn` : 'Empty: takes no damage'","onDamage":"(e,d,src)=>{
      if (src.key==='hound' && !(e.hold > 0)){ e.hold = 2; e.plan = planNext(e); log('The hound bites in and holds the Pelt open. Goku holds the leash.', 'foe'); }
      if (peltOpen(e)) return d;
      log(`${e.name} is empty: the hit passes through.`); fx(e.id, 'Empty'); return 0; }","holds":"(e,u)=>u.id==='goku' && e.hold > 0","holdText":"()=>'Goku holds the hound\'s leash and can\'t act.'","onTurn":"e=>{
      if (e.worn){ log(`The Pelt slips off ${e.worn.name}.`, 'foe'); e.worn = null; }
      if (e.hold > 0 && !gokuUp()){ e.hold = 0; log('With Goku down, the hound lets go.', 'foe'); } }","afterTurn":"e=>{ if (e.hold > 0 && --e.hold === 0) log('The hound lets go. The Pelt is empty again.', 'foe'); }","rules":[{"label":"The hound holds it open (it thrashes at Goku)","react":true,"when":"e=>e.hold > 0 && gokuUp()","skill":"thrash"},{"label":"This is its 4th, 8th, 12th… turn","when":"(e,n)=>n%4===0","skill":"wear"},{"label":"Otherwise","skill":"sleeve"}],"skills":{"sleeve":{"name":"Empty Sleeve","rank":3,"tags":["Physical","Stress"],"target":"random","power":"1.3× ATK","desc":"The arm is a person's: damage and +8 Stress. 10% crit chance.","run":"(e,t)=>{ hitParty(t, e.atk*1.3, {crit:Math.random()<e.crit, src:e}); if (t.alive) addStress(t, 8, 'Empty Sleeve'); }"},"thrash":{"name":"Thrash","rank":3,"tags":["Physical"],"target":"summoner","noProvoke":true,"power":"1.3× ATK","desc":"Held open, it fights the hound through Goku.","run":"(e,t)=>hitParty(t, e.atk*1.3, {src:e})"},"wear":{"name":"Put On","rank":3,"tags":["Physical","Stress"],"target":"lowest","power":"0.8× ATK","desc":"Damage and +15 Stress to the ally with the lowest HP%. Full, it takes damage until its next turn.","run":"(e,t)=>{ const b = t.blink; hitParty(t, e.atk*.8, {src:e}); if (t.alive && !b){ addStress(t, 15, 'Put On'); e.worn = t; log(`The Pelt puts on ${t.name}. Full, it can be hurt until its next turn.`, 'foe'); } }"}}}

scripts.rested:
{"notes":["Four identical sleepers. One is the original, and only it takes damage. They all show its HP.","A hit on a copy wakes it and shows it is a copy, but splits off a new sleeper (up to 6 bodies).","At the start of each sleeper's turn, the original rests: +1.5% HP. Sleeping copies take no turns, so they don't rest it.","Kiri's Lullaby puts every copy to sleep for 2 of its turns. The original never sleeps.","When the original falls, the copies go with it."],"init":"e=>{ e.seen = null; if (!G.enemies.some(x=>x.original)) pick(G.enemies.filter(x=>x.key==='rested')).original = true; }","hpOf":"()=>{ const o = G.enemies.find(x=>x.original); return { hp:o.hp, max:o.maxhp, text:`HP ${o.hp}/${o.maxhp}` }; }","status":"e=>e.seen==='copy' ? 'A copy' : e.seen==='original' ? 'The original' : ''","onTurn":"()=>{ const o = G.enemies.find(x=>x.original); if (o && o.alive && o.hp < o.maxhp){ const h = Math.min(o.maxhp - o.hp, Math.round(o.maxhp*.015)); o.hp += h; log(`The sleepers rest (+${h} HP).`, 'foe'); } }","onDamage":"(e,d)=>{
      if (e.original){ e.seen = 'original'; return d; }
      e.seen = 'copy'; if (e.sleep){ e.sleep = 0; e.plan = planNext(e); }
      if (G.enemies.filter(x=>x.key==='rested' && x.alive).length < 6){ const c = spawnPart(e, 'rested', SLOT*2); c.parentId = null; c.seen = null; log(`It was a copy. A new sleeper rolls out of it.`, 'foe'); }
      else log('It was a copy. There is no room for another.', 'foe');
      fx(e.id, 'A copy'); return 0; }","onPartyAct":"(e,u,act)=>{ if (act.kind!=='skill' || act.key!=='lullaby') return;
      if (e.original){ e.seen = 'original'; log('One of the sleepers does not close its eyes.', 'foe'); } else { e.sleep = 2; e.seen = 'copy'; } }","onDown":"e=>{ if (!e.original) return; G.enemies.filter(x=>x.key==='rested' && x.alive).forEach(x=>{ x.alive = false; x.hp = 0; }); log('The copies stop breathing with it.', 'foe'); }","rules":[{"label":"Every turn","roll":[[65,"yawn"],[35,"snore"]]}],"skills":{"yawn":{"name":"Yawn","rank":3,"tags":["Physical"],"target":"random","power":"0.9× ATK","desc":"Damage, and a 10% chance of Sleep: the target loses their next turn unless a hit wakes them first.","run":"(e,t)=>{ hitParty(t, e.atk*.9, {src:e}); if (t.alive && Math.random() < .1){ t.sleep = 1; log(`${t.name} falls asleep.`, 'dread'); } }"},"snore":{"name":"Snore","rank":3,"tags":["Sound","Stress"],"sound":true,"target":"all","power":"—","desc":"+10 Stress to each ally who can hear it.","run":"()=>targetsForFoes().forEach(t=>addStress(t, 10, 'Snore', {sound:true}))"}}}

scripts.tracks:
{"notes":["A copy of each of the three you brought, with their stats and 130% of their HP.","Each attack it copies also adds 10 Stress to whoever it hits.","On its turn a copy does what its original did on their last turn. If you attacked Natsu's copy, your copy attacks Natsu. A heal on an ally heals that ally's copy. Defend makes it brace.","Commands with nothing to copy (Soothe, Howl, Counter-Melody, Provoke, Mix, Foresee, Earplugs) do nothing when it repeats them."],"init":"(e,i)=>{ const o = actives()[i]; Object.assign(e, { of:o.id, name:`${o.name}'s Tracks`, maxhp:Math.round(o.maxhp*1.3), hp:Math.round(o.maxhp*1.3), atk:o.atk, def:o.def, mdef:o.def, mag:o.mag, agi:o.agi }); }","targetable":"e=>!e.air","hidden":"()=>'in the air'","status":"e=>{ const o = originOf(e); return `Copies ${o.name}: ${o.last ? actName(o.last) : 'nothing yet'}`; }","planName":"e=>e.air ? 'Landing' : originOf(e).last ? actName(originOf(e).last) : 'Wait'","planText":"e=>{ const o = originOf(e); if (e.air) return `Landing → ${e.landOn ? e.landOn.name : 'random ally'}`; if (!o.last) return 'Wait';
      const m = mirrorOf(o.last), t = mirrorTarget(e); return `${actName(o.last)} → ${m.all ? 'all' : t ? t.name : hostile(m) ? 'random ally' : e.name}`; }","onTurn":"e=>{ e.defending = false; e.counter = false; }","onDamage":"(e,d,src)=>{
      if (e.blink){ e.blink = false; fx(e.id, 'Dodge'); log(`${e.name} dodges.`); return 0; }
      if (e.defending) d = Math.round(d/2);
      if (e.cover){ e.cover = false; d = Math.round(d/2); log(`Cover halves the damage to ${e.name}.`); }
      if (e.counter && src.attacker && src.attacker.alive && d < e.hp){ log(`${e.name} counters ${src.attacker.name}.`, 'foe'); hitParty(src.attacker, e.atk*1.6); }
      return d; }","rules":[{"label":"Every turn","skill":"follow"}],"skills":{"follow":{"name":"Follow","rank":3,"rankOf":"e=>{ const a = originOf(e).last; return e.air || !a ? 3 : a.kind==='skill' ? (a.key==='jump' ? 5 : SKILLS[a.key].delay) : a.kind==='limit' ? 4 : 3; }","tags":["Mirror"],"target":"mirror","power":"As its original's command","desc":"Repeats its original's last command at the same power, turned back on the party. Its Delay is that command's Delay.","run":"e=>mirrorRun(e)"}}}

scripts.greyhound:
{"notes":["It can't be KO'd. Every hit raises its ATK 10% instead.","Goku acts on her own. On her turn, if her Stress is under 50, she calls the hound back one step. Three steps end the fight.","Each of its attacks adds 20 Stress to Goku as well, or 10 if its target is Defending and holds it back."],"init":"e=>{ e.steps = 0; }","hpOf":"e=>({ hp:3 - e.steps, max:3, text:`Steps from Goku: ${3 - e.steps}` })","status":"e=>`ATK ${e.atk}`","onDamage":"e=>{ e.atk = Math.round(e.atk*1.1); log(`${e.name} can't be hurt. The hit only angers it: ATK ${e.atk}.`, 'foe'); fx(e.id, 'ATK +10%'); return 0; }","guestTurn":"(e,u)=>{
      if (u.stress >= 50){ log(`Goku is at ${u.stress} Stress and can't find her voice.`, 'dread'); return; }
      e.steps++; fx(e.id, `${e.steps}/3`); log(`Goku calls the hound back (${e.steps} of 3).`, 'dread');
      if (e.steps >= 3){ e.alive = false; e.hp = 0; log('The hound lies down at Goku\'s feet.', 'foe'); } }","rules":[{"label":"This is its 3rd, 6th, 9th… turn","when":"(e,n)=>n%3===0","skill":"pounce"},{"label":"Otherwise","skill":"bite"}],"skills":{"bite":{"name":"Bite","rank":3,"tags":["Physical","Stress"],"target":"random","power":"1.4× ATK","desc":"Damage, and +20 Stress to Goku (+10 if the target is Defending: they hold it back).","run":"(e,t)=>{ const held = t.defending; hitParty(t, e.atk*1.4, {crit:Math.random()<e.crit, src:e}); addStress(byId('goku'), held ? 10 : 20, held ? 'the hound, held back' : 'the hound'); }"},"pounce":{"name":"Pounce","rank":3,"tags":["Physical","Stress"],"target":"lowest","power":"2.0× ATK","desc":"Damage to the ally with the lowest HP%, and +20 Stress to Goku (+10 if the target is Defending).","run":"(e,t)=>{ const held = t.defending; hitParty(t, e.atk*2.0, {src:e}); addStress(byId('goku'), held ? 10 : 20, held ? 'the hound, held back' : 'the hound'); }"}}}

scripts.listener:
{"notes":["Already dead: at 0 HP it is only knocked into its coffin.","Before the Abbot's next turn, an ally who didn't knock it in must seal the coffin with any item (use the item on it). Otherwise it climbs out at full HP."],"status":"e=>e.coffin ? `In its coffin: seal it with an item from anyone but ${byId(e.knockedBy) ? byId(e.knockedBy).name : 'whoever knocked it in'}` : ''","hpOf":"e=>e.coffin ? { hp:0, max:e.maxhp, text:'In its coffin' } : null","onDamage":"(e,d,src)=>{
      if (e.coffin){ log(`${e.name} is already in its coffin.`); return 0; }
      if (d < e.hp) return d;
      e.hp = 0; e.coffin = true; e.knockedBy = src.attacker ? src.attacker.id : null; e.plan = planNext(e); fx(e.id, 'Coffin'); shake(e.id);
      log(`${e.name} is knocked back into its coffin. Seal it with an item before the Abbot's next turn.`, 'foe'); return 0; }","takesItem":"(e,u)=>e.coffin && u.id!==e.knockedBy","onItem":"e=>{ e.coffin = false; e.sealed = true; e.alive = false; e.hp = 0; log(`The coffin is sealed. ${e.name} stays down.`, 'foe'); }","rules":[{"label":"It is in its coffin","react":true,"when":"e=>!!e.coffin","skill":"lie"},{"label":"Otherwise","roll":[[70,"touch"],[30,"listen"]]}],"skills":{"lie":{"name":"Lie Still","rank":3,"tags":[],"target":"none","power":"—","desc":"In its coffin, it does nothing.","run":"()=>{}"},"touch":{"name":"Dry Touch","rank":3,"tags":["Physical","Paralyze"],"target":"random","power":"1.2× ATK","desc":"A 20% chance of Paralyze for 2 turns.","run":"(e,t)=>{ hitParty(t, e.atk*1.2, {src:e}); inflict(t, 'Paralyze', 2, 20); }"},"listen":{"name":"Listen","rank":3,"tags":["Stress"],"target":"brink","power":"—","desc":"It listens to your heart: +10 Stress to the ally closest to a Stress Check.","run":"(e,t)=>addStress(t, 10, 'Listen')"}}}

scripts.mirenslot:
{"hint":"Every time he moves, they move.","notes":["One turn shared by every copy: each turn, the next copy in line acts. Every time the real Miren acts, the copies take a turn right after him.","A copy in the air can't be targeted; it lands on its next action.","Each copy defeated pushes the real Miren back 2 slots."],"phases":[{"id":"p1","label":"More than 2 copies left"},{"id":"p2","label":"2 copies or fewer: they Jump every turn","when":"()=>mirenCopies().length<=2","free":true}],"parts":[{"key":"mirencopy","respawn":0,"label":"Miren ×4 (copies from the save points)"}],"init":"e=>{ e.rot = 0; e.leap = Math.random() < .4; }","targetable":"()=>false","hidden":"()=>'it is a turn, not a body'","hpOf":"()=>({ hp:mirenCopies().length, max:4, text:`${mirenCopies().length} Mirens left` })","planName":"e=>{ const c = nextCopy(e); return !c ? '' : c.air ? 'Land' : (p2(e) || e.leap) ? 'Jump' : 'Spear'; }","planText":"e=>{ const c = nextCopy(e); if (!c) return ''; return `${c.name} ${c.id.slice(1)}: ${c.air ? `Land → ${c.landOn ? c.landOn.name : 'random ally'}` : (p2(e) || e.leap) ? 'Jump' : 'Spear → random ally'}`; }","onPartyAct":"(e,u)=>{ if (u.id==='miren' && !u.airborne && mirenCopies().length) e.ct = Math.min(e.ct, 1); }","afterTurn":"e=>{ e.rot++; e.leap = Math.random() < .4; }","rules":[{"label":"Every turn","skill":"turn"}],"skills":{"turn":{"name":"The Next Miren","rank":3,"tags":["Physical"],"target":"none","power":"1.4× ATK (Spear), 3.2× ATK (Land)","desc":"The next copy in line: lands if it is in the air, Jumps (40%, always in phase 2), or thrusts with its Spear (+10 Stress).","run":"e=>{ const c = nextCopy(e), ts = targetsForFoes(); if (!c || !ts.length) return;
        if (c.air){ const t = ts.includes(c.landOn) ? c.landOn : pick(ts); c.air = false; c.landOn = null; log(`A Miren lands.`, 'foe'); hitParty(t, c.atk*3.2, {src:c}); }
        else if (p2(e) || e.leap){ c.air = true; c.landOn = pick(ts); log(`A Miren Jumps. He'll land on ${c.landOn.name}.`, 'foe'); }
        else { const t = pick(ts); log(`A Miren thrusts at ${t.name}.`, 'foe'); hitParty(t, c.atk*1.4, {crit:Math.random()<c.crit, src:c}); if (t.alive) addStress(t, 10, 'a Miren\'s spear'); } }"}}}

scripts.facethief:
{"hint":"Give them back their faces.","notes":["Each missing feature: −20% ATK, DEF and MAG. Missing all three: KO'd (the face comes back with them), and she heals 25%.","A round is the time between two of her turns. A feature comes back when, in the same round, an ally heals its owner and anyone hits her.","In this fight Tetsugi's Chakra can be aimed at an ally."],"phases":[{"id":"p1","label":"Above 50% HP"},{"id":"p2","label":"50% HP or below: she takes only Kiri's face, and only Tetsugi's Chakra gives it back","when":"e=>e.hp<=e.maxhp/2","free":true}],"init":"e=>{ e.healed = new Set(); e.hit = false; }","onTurn":"e=>{ e.healed = new Set(); e.hit = false; }","onDamage":"(e,d,src)=>{ if (src.attacker){ e.hit = true; giveBack(e); } return d; }","onHeal":"(e,t,healer)=>{ if (!(t.lost || []).length) return;
      if (p2(e) && t.id==='kiri' && !(healer && healer.id==='tetsugi' && G.hitKey==='chakra')){ log('Only Tetsugi\'s Chakra can give Kiri her face back now.', 'dread'); return; }
      e.healed.add(t.id); giveBack(e); }","rules":[{"phase":"p2","label":"Phase 2: Kiri is here","when":"()=>targetsForFoes().some(t=>t.id==='kiri')","skill":"stare","target":"kiri"},{"label":"Otherwise","skill":"stare"}],"skills":{"stare":{"name":"Stare","rank":3,"tags":["Stress","Confuse"],"target":"random","noProvoke":true,"power":"—","desc":"Steals a feature (eyes, nose, then mouth): −20% stats, +10 Stress, a 30% chance of Confuse for 2 turns. The third one KOs and heals her 25%.","run":"(e,t)=>{ t.lost = t.lost || []; const f = FEATURES.find(x=>!t.lost.includes(x)); t.lost.push(f); applyFace(t);
        log(`The Face Thief takes ${t.name}'s ${f}.`, 'foe'); fx(t.id, `No ${f}`); addStress(t, 10, 'faceless');
        if (t.lost.length >= 3){ t.lost = []; applyFace(t); ko(t); const h = Math.min(e.maxhp - e.hp, Math.round(e.maxhp*.25)); e.hp += h; fx(e.id, `+${h}`, 'heal'); log(`She wears it. +${h} HP.`, 'foe'); }
        else inflict(t, 'Confuse', 2, 30); }"}}}

scripts.congregation:
{"planName":"e=>e.phase && phaseOf(e)!==e.phase ? 'Phase change' : null","planText":"e=>e.phase && phaseOf(e)!==e.phase ? 'Phase change → action will be chosen when it acts' : null","hint":"Look where it isn't looking.","notes":["It takes no damage from the ally it is staring at, and the stare adds 10 Stress to them at the start of each of its turns.","Above 50% HP, a critical hit or a Limit Break pulls the stare onto whoever landed it.","At 50% HP it splits into 3 Faces, each staring at a different active ally. Each Face can be hurt only by the other two."],"phases":[{"id":"p1","label":"Above 50% HP"},{"id":"p2","label":"50% HP or below: it splits into 3 Faces","when":"e=>e.hp<=e.maxhp/2","free":true,"enterFn":"e=>{ if (G.split) return; G.split = true; e.name = 'Face of the Congregation'; const ts = shuffled(targetsForFoes());
                 for (let i=0;i<2;i++){ const f = spawnPart(e, 'congregation', SLOT*(2+i)); f.parentId = null; f.name = 'Face of the Congregation'; f.maxhp = f.hp = Math.round(e.maxhp*.3); f.phase = 'p2'; f.stare = null; }
                 const faces = G.enemies.filter(x=>x.key==='congregation' && x.alive); faces.forEach(f=>{ f.stare = null; });
                 faces.forEach((f,i)=>{ f.stare = (ts[i] || pick(targetsForFoes())).id; });
                 log(`The Congregation splits into 3 Faces: they stare at ${faces.map(f=>byId(f.stare).name).join(', ')}.`, 'foe'); }"}],"init":"e=>{ const ts = targetsForFoes(); e.stare = (ts.find(t=>t.id==='natsu') || pick(ts)).id; }","status":"e=>e.stare ? `Staring at ${byId(e.stare).name}: no damage from them` : ''","onTurn":"e=>{ restare(e); const t = byId(e.stare); if (t && targetsForFoes().includes(t)) addStress(t, 10, 'stared at'); }","onDamage":"(e,d,src)=>{ const a = src.attacker; if (!a) return d;
      if (a.id===e.stare){ log(`${e.name} is staring at ${a.name}: the hit does nothing.`); fx(e.id, 'Watching'); return 0; }
      if (!G.split && (src.crit || src.key==='limit')){ e.stare = a.id; log(`The Congregation's stare moves to ${a.name}.`, 'foe'); }
      return d; }","onPartyAct":"(e,u,act)=>{ if (!G.split && act.kind==='limit' && e.stare!==u.id){ e.stare = u.id; log(`The Congregation's stare moves to ${u.name}.`, 'foe'); } }","rules":[{"label":"Every turn","roll":[[60,"verdict"],[40,"murmur"]]}],"skills":{"verdict":{"name":"Verdict","rank":3,"tags":["Physical","Confuse"],"target":"random","power":"1.4× ATK","desc":"A 30% chance of Confuse for 2 turns.","run":"(e,t)=>{ hitParty(t, e.atk*1.4, {crit:Math.random()<e.crit, src:e}); inflict(t, 'Confuse', 2, 30); }"},"murmur":{"name":"Murmur","rank":3,"tags":["Sound","Stress"],"sound":true,"target":"all","power":"—","desc":"+8 Stress to each ally who can hear it.","run":"()=>targetsForFoes().forEach(t=>addStress(t, 8, 'Murmur', {sound:true}))"}}}

scripts.sleeper:
{"noTurn":true,"hpOf":"e=>({ hp:e.awake ? 1 : 0, max:1, text:e.awake===Infinity ? 'Awake for good' : e.awake ? `Awake for ${e.awake} more of its turns` : `Humming (woken ${e.woken || 0} of 4)` })","onDamage":"(e,d,src)=>{ if (!src.attacker) return 0;
      if (e.awake){ log(`${e.name} is already awake.`); return 0; }
      e.woken = (e.woken || 0) + 1; e.awake = e.woken >= 4 ? Infinity : 2; fx(e.id, 'Awake');
      log(e.woken >= 4 ? `${e.name} wakes up for the fourth time, and stays awake. It is someone from Ostrel.` : `${e.name} wakes up. It is someone from Ostrel.`, 'foe');
      // One action that wakes several at once (Darkga) costs the 10 Stress once.
      if (!(src.area && G.woke)) addStress(src.attacker, 10, 'woke a villager'); if (src.area) G.woke = true; return 0; }","rules":[{"label":"Every turn","skill":"hum"}],"skills":{"hum":{"name":"Hum","rank":3,"tags":[],"target":"none","power":"—","desc":"It never acts. While it hums, Taste of Ostrel heals 5% a turn. A hit wakes it for 2 of the boss's turns: no damage, and +10 Stress to the ally who woke it (once per action, however many wake). Woken a fourth time, it stays awake for good.","run":"()=>{}"}}}
